from decimal import Decimal, InvalidOperation, localcontext


def safe_decimal(value: str) -> Decimal:
    """Convert a string to Decimal, raising ValueError on failure."""
    try:
        return Decimal(value.strip())
    except (InvalidOperation, AttributeError, TypeError) as e:
        raise ValueError(f"Invalid decimal value: {value!r}") from e


def quantize_currency(d: Decimal) -> Decimal:
    """Round a Decimal to 2 decimal places (currency precision)."""
    with localcontext() as ctx:
        ctx.prec = 28
        return d.quantize(Decimal("0.01"), rounding=ctx.ROUND_HALF_UP)


def format_currency(d: Decimal) -> str:
    """Format a Decimal as a currency string with 2 decimal places."""
    return f"{quantize_currency(d):.2f}"

