from dataclasses import dataclass
from datetime import date
from decimal import Decimal
from typing import List, Optional


@dataclass
class ValidationError:
    """Represents a validation error for a single field."""
    field: str
    message: str
    record_index: int


class ExpenseValidator:
    """Validate individual expense records."""

    REQUIRED_FIELDS = {"date", "category", "amount", "description"}

    def __init__(self, max_amount: Optional[Decimal] = None):
        self.max_amount = max_amount

    def validate(self, record, index: int = 0) -> List[ValidationError]:
        """Validate an ExpenseRecord and return a list of errors."""
        errors: List[ValidationError] = []

        # Check required fields exist on the record
        for field in self.REQUIRED_FIELDS:
            value = getattr(record, field, None)
            if value is None or value == "":
                errors.append(ValidationError(
                    field=field,
                    message=f"Missing required field '{field}'",
                    record_index=index,
                ))

        # Validate date field
        if hasattr(record, "date") and record.date is not None:
            if not isinstance(record.date, date):
                errors.append(ValidationError(
                    field="date",
                    message=f"Invalid date type: expected date, got {type(record.date).__name__}",
                    record_index=index,
                ))

        # Validate amount field
        if hasattr(record, "amount") and record.amount is not None:
            if not isinstance(record.amount, Decimal):
                errors.append(ValidationError(
                    field="amount",
                    message=f"Invalid amount type: expected Decimal, got {type(record.amount).__name__}",
                    record_index=index,
                ))
            elif record.amount < 0:
                errors.append(ValidationError(
                    field="amount",
                    message=f"Amount cannot be negative: {record.amount}",
                    record_index=index,
                ))
            if self.max_amount is not None and record.amount > self.max_amount:
                errors.append(ValidationError(
                    field="amount",
                    message=f"Amount {record.amount} exceeds maximum {self.max_amount}",
                    record_index=index,
                ))

        return errors

    def is_valid(self, record, index: int = 0) -> bool:
        """Return True if the record has no validation errors."""
        return len(self.validate(record, index)) == 0

