import json
from datetime import date
from decimal import Decimal
from typing import Dict, Iterable, List, Optional

from expense_reporter.parser import ExpenseRecord
from expense_reporter.decimal_utils import format_currency


class MarkdownReporter:
    """Generate Markdown summary reports."""

    def generate(self, records: Iterable[ExpenseRecord], title: str = "Expense Report") -> str:
        """Generate a Markdown report from expense records."""
        records_list = list(records)
        lines = [
            f"# {title}",
            f"",
            f"**Generated:** {date.today().isoformat()}",
            f"**Total records:** {len(records_list)}",
            f"**Total amount:** {self._sum_amount(records_list)}",
            f"",
            f"## Summary by Category",
            f"",
        ]

        category_totals = self._group_by_category(records_list)
        for category, total in sorted(category_totals.items()):
            lines.append(f"- **{category}**: {total}")

        lines.append("")
        lines.append("## Records")
        lines.append("")
        lines.append("| Date | Category | Amount | Description |")
        lines.append("|------|----------|--------|-------------|")
        for r in records_list:
            lines.append(
                f"| {r.date.isoformat()} | {r.category} | {format_currency(r.amount)} | {r.description} |"
            )
        lines.append("")
        return "\n".join(lines)

    def _sum_amount(self, records: List[ExpenseRecord]) -> str:
        total = sum((r.amount for r in records), Decimal("0"))
        return format_currency(total)

    def _group_by_category(self, records: List[ExpenseRecord]) -> Dict[str, str]:
        totals: Dict[str, Decimal] = {}
        for r in records:
            totals[r.category] = totals.get(r.category, Decimal("0")) + r.amount
        return {cat: format_currency amt) for cat, amt in totals.items()}


class JsonReporter:
    """Generate JSON output for expense data."""

    def generate(self, records: Iterable[ExpenseRecord]) -> str:
        """Generate a JSON report from expense records."""
        records_list = list(records)
        payload = {
            "generated": date.today().isoformat(),
            "total_records": len(records_list),
            "total_amount": format_currency(
                sum((r.amount for r in records_list), Decimal("0"))
            ),
            "records": [
                {
                    "date": r.date.isoformat(),
                    "category": r.category,
                    "amount": format_currency(r.amount),
                    "description": r.description,
                    "receipt_number": r.receipt_number,
                }
                for r in records_list
            ],
        }
        return json.dumps(payload, indent=2, ensure_ascii=False)

