    REQUIRED_FIELDS = {"date", "category", "amount", "description"}

    def __init__(self, max_amount: Optional[Decimal] = None):
        self.max_amount = max_amount

    def validate(self, record, index: int = 0) -> List[ValidationError]:
        """Validate an ExpenseRecord and return a list of errors."""
        errors: List[ValidationError] = []

        # Check required fields exist on the record
        for field in self.REQUIRED_FIELDS:
            value = getattr(record, field, None)
            if value is None or value == "":
                errors.append(ValidationError(
                    field=field,
                    message=f"Missing required field '{field}'",
                    record_index=index,
                ))

        # Validate date field
        if hasattr(record, "date") and record.date is not None:
            if not isinstance(record.date, date):
                errors.append(ValidationError(
                    field="date",
                    message=f"Invalid date type: expected date, got {type(record.date).__name__}",
                    record_index=index,
                ))

        # Validate amount field
        if hasattr(record, "amount") and record.amount is not None:
            if not isinstance(record.amount, Decimal):
                errors.append(ValidationError(
                    field="amount",
                    message=f"Invalid amount type: expected Decimal, got {type(record.amount).__name__}",
                    record_index=index,
                ))
            elif record.amount < 0:
                errors.append(ValidationError(
                    field="amount",
                    message=f"Amount cannot be negative: {record.amount}",
                    record_index=index,
                ))
            if self.max_amount is not None and record.amount > self.max_amount:
                errors.append(ValidationError(
                    field="amount",
                    message=f"Amount {record.amount} exceeds maximum {self.max_amount}",
                    record_index=index,
                ))

        return errors

    def is_valid(self, record, index: int = 0) -> bool:
        """Return True if the record has no validation errors."""
        return len(self.validate(record, index)) == 0

"""Report generation modules for expense data."""

import json
from datetime import date
from decimal import Decimal
from typing import Dict, Iterable, List

from expense_reporter.parser import ExpenseRecord
from expense_reporter.decimal_utils import format_currency


class MarkdownReporter:
    """Generate Markdown summary reports."""

    def generate(self, records: Iterable[ExpenseRecord], title: str = "Expense Report") -> str:
        """Generate a Markdown report from expense records."""
        records_list = list(records)
        lines = [
            f"# {title}",
            f"",
            f"**Generated:** {date.today().isoformat()}",
            f"**Total records:** {len(records_list)}",
            f"**Total amount:** {self._sum_amount(records_list)}",
            f"",
            f"## Summary by Category",
            f"",
        ]

        category_totals = self._group_by_category(records_list)
        for category, total in sorted(category_totals.items()):
            lines.append(f"- **{category}**: {total}")

        lines.append("")
        lines.append("## Records")
        lines.append("")
        lines.append("| Date | Category | Amount | Description |")
        lines.append("|------|----------|--------|-------------|")
        for r in records_list:
            lines.append(
                f"| {r.date.isoformat()} | {r.category} | {format_currency(r.amount)} | {r.description} |"
            )
        lines.append("")
        return "\n".join(lines)

    def _sum_amount(self, records: List[ExpenseRecord]) -> str:
        total = sum((r.amount for r in records), Decimal("0"))
        return format_currency(total)

    def _group_by_category(self, records: List[ExpenseRecord]) -> Dict[str, str]:
        totals: Dict[str, Decimal] = {}
        for r in records:
            totals[r.category] = totals.get(r.category, Decimal("0")) + r.amount
        return {cat: format_currency(amt) for cat, amt in totals.items()}


