"""Decimal utilities for expense processing."""

from decimal import Decimal, InvalidOperation, localcontext


def safe_decimal(value: str) -> Decimal:
    """Convert a string to Decimal, raising ValueError on failure."""
    try:
        return Decimal(value.strip())
    except (InvalidOperation, AttributeError, TypeError) as e:
        raise ValueError(f"Invalid decimal value: {value!r}") from e


def quantize_currency(d: Decimal) -> Decimal:
    """Round a Decimal to 2 decimal places (currency precision)."""
    with localcontext() as ctx:
        ctx.prec = 28
        return d.quantize(Decimal("0.01"), rounding=ctx.ROUND_HALF_UP)


def format_currency(d: Decimal) -> str:
    """Format a Decimal as a currency string with 2 decimal places."""
    return f"{quantize_currency(d):.2f}"

"""Deduplication module for expense records."""

from typing import Iterable, List, Optional
from expense_reporter.parser import ExpenseRecord


class Deduplicator:
    """Remove duplicate expense records."""

    def __init__(self, key_fields=None):
        """
        Initialize deduplicator.

        Args:
            key_fields: Tuple of field names to use as dedup key.
                        Defaults to (date, category, amount, receipt_number).
        """
        if key_fields is None:
            key_fields = ("date", "category", "amount", "receipt_number")
        self.key_fields = key_fields

    def deduplicate(self, records: Iterable[ExpenseRecord]) -> List[ExpenseRecord]:
        """Return a list of records with duplicates removed."""
        seen = set()
        result = []
        for record in records:
            key = self._make_key(record)
            if key not in seen:
                seen.add(key)
                result.append(record)
        return result

    def _make_key(self, record: ExpenseRecord) -> tuple:
        """Create a hashable key from the record's key fields."""
        return tuple(getattr(record, f, None) for f in self.key_fields)

    def get_duplicate_count(self, records: Iterable[ExpenseRecord]) -> int:
        """Return the number of duplicate records found."""
        seen = set()
        duplicates = 0
        for record in records:
            key = self._make_key(record)
            if key in seen:
                duplicates += 1
            else:
                seen.add(key)
        return duplicates

